// Нормализация как в src/utils/ingredientMappingCore.ts
function normalizeClientName(name: string): string {
  return name.toLowerCase().replace(/\.(webp|png)$/i,"").replace(/_*(результат)$/i,"").replace(/\)+$/,"").replace(/_+$/,"").replace(/\.+$/,"").replace(/%/g,"").replace(/[_\s]+/g," ").replace(/ё/g,"е").trim();
}

