function stripParentheses(s: string): string {
  return s.replace(/\(.*?\)/g, " ").replace(/\s+/g, " ").trim();
}
function stripModifiers(s: string): string {
  const parts = s.split(/\s+/).filter(Boolean);
  const filtered = parts.filter((w) => !MODIFIER_WORDS_NORM.has(w));
  return filtered.join(" ").trim();
}

/**
 * Сопоставление названия ингредиента (как в dish.ingredients[].name) с профилем на 100г.
 * Порядок: точное -> BOOK_SYNONYMS -> ручные fallback -> без скобок/без модификаторов -> усечение -> скан по словам.
 * Read-Only, без обращения к серверу/BD.
 */
export function getClientProfile(rawName: string): ClientNutrientProfile | null {
  if (!rawName) return null;
  const n = normalizeClientName(rawName);
  if (!n) return null;
  const direct = (CLIENT_NUTRIENT_DB as any)[n] as ClientNutrientProfile | undefined;
  if (direct) return direct;
  const manualDirect = (MANUAL_ALIAS_FALLBACK as any)[n] as string | undefined;
  if (manualDirect) {
    const viaManualDirect = (CLIENT_NUTRIENT_DB as any)[normalizeClientName(manualDirect)] as ClientNutrientProfile | undefined;
    if (viaManualDirect) return viaManualDirect;
  }
  const aliasTarget = (BOOK_SYNONYMS_NORM as any)[n] as string | undefined;
  if (aliasTarget) {
    const viaAlias = (CLIENT_NUTRIENT_DB as any)[aliasTarget] as ClientNutrientProfile | undefined;
    if (viaAlias) return viaAlias;
    const manual = MANUAL_ALIAS_FALLBACK[aliasTarget];
    if (manual) {
      const viaManual = (CLIENT_NUTRIENT_DB as any)[normalizeClientName(manual)] as ClientNutrientProfile | undefined;
      if (viaManual) return viaManual;
    }
    // Попытка без скобок/без модификаторов для aliasTarget
    const aliasStripped = stripModifiers(stripParentheses(aliasTarget));
    if (aliasStripped && aliasStripped !== aliasTarget) {
      const viaStripped = (CLIENT_NUTRIENT_DB as any)[aliasStripped] as ClientNutrientProfile | undefined;
      if (viaStripped) return viaStripped;
    }
  }
  // Без скобок и без модификаторов для исходного имени (ловит "овсяные хлопья (долгого приготовления)" -> "овсяные хлопья")
  const nNoParen = stripParentheses(n);
  if (nNoParen !== n) {
    const byNoParen = (CLIENT_NUTRIENT_DB as any)[nNoParen] as ClientNutrientProfile | undefined;
    if (byNoParen) return byNoParen;
    const aliasNoParen = (BOOK_SYNONYMS_NORM as any)[nNoParen] as string | undefined;
    if (aliasNoParen) {
      const viaAliasNoParen = (CLIENT_NUTRIENT_DB as any)[aliasNoParen] as ClientNutrientProfile | undefined;
      if (viaAliasNoParen) return viaAliasNoParen;
      const manual2 = MANUAL_ALIAS_FALLBACK[aliasNoParen];
      if (manual2) {
        const viaManual2 = (CLIENT_NUTRIENT_DB as any)[normalizeClientName(manual2)] as ClientNutrientProfile | undefined;
        if (viaManual2) return viaManual2;
      }
    }
  }
  const nStripped = stripModifiers(nNoParen !== n ? nNoParen : n);
  if (nStripped && nStripped !== n && nStripped !== nNoParen) {
    const byStripped = (CLIENT_NUTRIENT_DB as any)[nStripped] as ClientNutrientProfile | undefined;
    if (byStripped) return byStripped;
  }
  // Fallback: последовательное усечение
  const parts = n.split(/\s+/).filter(Boolean);
  for (let i = parts.length - 1; i >= 1; i--) {
    const trunc = parts.slice(0, i).join(" ");
    const byTrunc = (CLIENT_NUTRIENT_DB as any)[trunc] as ClientNutrientProfile | undefined;
    if (byTrunc) return byTrunc;
    const aliasTrunc = (BOOK_SYNONYMS_NORM as any)[trunc] as string | undefined;
    if (aliasTrunc) {
      const viaAliasTrunc = (CLIENT_NUTRIENT_DB as any)[aliasTrunc] as ClientNutrientProfile | undefined;
      if (viaAliasTrunc) return viaAliasTrunc;
      const manualT = MANUAL_ALIAS_FALLBACK[aliasTrunc];
      if (manualT) {
        const viaManualT = (CLIENT_NUTRIENT_DB as any)[normalizeClientName(manualT)] as ClientNutrientProfile | undefined;
        if (viaManualT) return viaManualT;
      }
    }
  }
  for (const w of parts) {
    const byWord = (CLIENT_NUTRIENT_DB as any)[w] as ClientNutrientProfile | undefined;
    if (byWord) return byWord;
  }
  // Финальный скан: перестановка слов (капуста цветная <-> цветная капуста) и подмножество слов
  const nWordsStripped = new Set(stripModifiers(nNoParen !== n ? nNoParen : n).split(/\s+/).filter(Boolean));
  if (nWordsStripped.size > 0) {
    let best: { key: string; score: number } | null = null;
    for (const dbKey of Object.keys(CLIENT_NUTRIENT_DB)) {
      const dbStripped = stripModifiers(stripParentheses(dbKey));
      const dbWords = new Set(dbStripped.split(/\s+/).filter(Boolean));
      if (dbWords.size === 0) continue;
      // проверяем что все слова DB есть в input или наоборот
      const allDbInInput = [...dbWords].every((w) => nWordsStripped.has(w));
      const allInputInDb = [...nWordsStripped].every((w) => dbWords.has(w));
      if (allDbInInput || allInputInDb) {
        const score = Math.min(dbWords.size, nWordsStripped.size);
        if (!best || score > best.score) best = { key: dbKey, score };
        if (score === dbWords.size && score === nWordsStripped.size) break; // exact set match
      }
    }
    if (best) {
      const viaScan = (CLIENT_NUTRIENT_DB as any)[best.key] as ClientNutrientProfile | undefined;
      if (viaScan) return viaScan;
    }
  }
  return null;
}
